ON DUPLICATE KEY UPDATE energy_kcal = IF(clinic_id IS NULL AND is_custom = 0, VALUES(energy_kcal), energy_kcal), protein_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(protein_g), protein_g), lipid_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(lipid_g), lipid_g), carbohydrate_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(carbohydrate_g), carbohydrate_g), fiber_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(fiber_g), fiber_g), nutrient_flags = IF(clinic_id IS NULL AND is_custom = 0, VALUES(nutrient_flags), nutrient_flags), category = IF(clinic_id IS NULL AND is_custom = 0, COALESCE(category, VALUES(category)), category);

ON DUPLICATE KEY UPDATE energy_kcal = IF(clinic_id IS NULL AND is_custom = 0, VALUES(energy_kcal), energy_kcal), protein_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(protein_g), protein_g), lipid_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(lipid_g), lipid_g), carbohydrate_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(carbohydrate_g), carbohydrate_g), fiber_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(fiber_g), fiber_g), nutrient_flags = IF(clinic_id IS NULL AND is_custom = 0, VALUES(nutrient_flags), nutrient_flags), category = IF(clinic_id IS NULL AND is_custom = 0, COALESCE(category, VALUES(category)), category);

ON DUPLICATE KEY UPDATE energy_kcal = IF(clinic_id IS NULL AND is_custom = 0, VALUES(energy_kcal), energy_kcal), protein_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(protein_g), protein_g), lipid_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(lipid_g), lipid_g), carbohydrate_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(carbohydrate_g), carbohydrate_g), fiber_g = IF(clinic_id IS NULL AND is_custom = 0, VALUES(fiber_g), fiber_g), nutrient_flags = IF(clinic_id IS NULL AND is_custom = 0, VALUES(nutrient_flags), nutrient_flags), category = IF(clinic_id IS NULL AND is_custom = 0, COALESCE(category, VALUES(category)), category);

-- 4) Alimentos com energia/macros "*" (não inseridos): se já existem vinculados, só recebem a marcação.
UPDATE foods SET nutrient_flags = 'energy_kcal=*;protein_g=*;lipid_g=*;carbohydrate_g=*;fiber_g=*' WHERE taco_code = 450 AND clinic_id IS NULL AND is_custom = 0;
UPDATE foods SET nutrient_flags = 'energy_kcal=*;protein_g=*;lipid_g=*;carbohydrate_g=*;fiber_g=NA' WHERE taco_code = 457 AND clinic_id IS NULL AND is_custom = 0;
UPDATE foods SET nutrient_flags = 'energy_kcal=*;protein_g=*;lipid_g=*;carbohydrate_g=*;fiber_g=NA' WHERE taco_code = 458 AND clinic_id IS NULL AND is_custom = 0;
UPDATE foods SET nutrient_flags = 'energy_kcal=*;protein_g=*;lipid_g=*;carbohydrate_g=*;fiber_g=*' WHERE taco_code = 591 AND clinic_id IS NULL AND is_custom = 0;

COMMIT;

-- 5) Conferência (esperado: taco_vinculados = 594 (593 + leite desnatado de referência vinculado ao nº 457), ou 593 sem ele; clinica_com_taco = 0)
SELECT COUNT(*) AS taco_vinculados, SUM(clinic_id IS NOT NULL) AS clinica_com_taco FROM foods WHERE taco_code IS NOT NULL;
